package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: the amount is required, a number with up to two decimals (negative only for a correction); the date is blank or yyyy-MM-dd. */
public class ValidateClaim {
    public void validate(@RequestBody ClaimRequest request, Out<ClaimValues> values) throws InvalidClaimException {
        values.set(ClaimValues.from(request));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Loads a claim of the sheet by id; one not on the sheet is a 404. */
public class LoadClaim {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") String claimId,
            ClaimRepository claims, Out<Claim> claim) throws ClaimNotFoundException {
        Claim found;
        try {
            found = claims.find(sheetId.trim(), Long.parseLong(claimId.trim()));
        } catch (NumberFormatException e) {
            found = null;
        }
        if (found == null) {
            throw new ClaimNotFoundException("No claim " + claimId);
        }
        claim.set(found);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Applies the edited values; only a DRAFT claim can be edited (an open claim is voided and a new one added instead),
 * and a claim dated inside a closed period, or moved into one, or moved after its person's retirement date, is refused. */
public class ApplyClaim {
    public void apply(@Val Claim claim, @Val ClaimValues values, SheetRepository sheets, PeriodRepository periods,
            PersonRepository people, ClaimRepository claims, Out<Claim> changed) throws InvalidClaimException {
        if (claim.status() != ClaimStatus.DRAFT) {
            throw new InvalidClaimException("Only a DRAFT claim can be edited");
        }
        LocalDate date = values.date() != null ? values.date() : sheets.today(claim.sheetId());
        if (periods.closedOn(claim.sheetId(), claim.date()) || periods.closedOn(claim.sheetId(), date)) {
            throw new InvalidClaimException("The claim's date is inside a closed period");
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        if (person != null && !date.equals(claim.date()) && !person.mayClaimOn(date)) {
            throw new InvalidClaimException("The claim's date is after the person's retirement date");
        }
        changed.set(new Claim(claim.id(), claim.sheetId(), claim.personId(), values.amount(), date, values.note(), claim.status(),
                claim.number(), claim.due(), claim.openedBy(), claim.stated(), claim.statedDue(),
                Corrections.check(claim.sheetId(), claim.personId(), values, claims), claim.dueBy(), claim.deferredUntil(), claim.proofs(), claim.splitFrom()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

public class SaveClaim {
    public void save(@Val Claim claim, ClaimRepository claims) throws InvalidClaimException {
        if (!claims.update(claim)) {
            throw new InvalidClaimException("Only a DRAFT claim can be edited");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Writes CLAIM_EDITED to the audit file once the edit is stored. Then writes the
 * figures the change moved (see Rollup). */
public class RecordClaimEdited {
    public void record(@Val Claim claim, @Val ClaimValues values, PersonRepository people, @Val RollupBefore before, Rollup rollup, Audit audit) {
        Person person = people.find(claim.sheetId(), claim.personId());
        audit.record("CLAIM_EDITED sheet=" + claim.sheetId() + " by=" + values.by() + " person="
                + (person == null ? "" : person.name()) + " amount=" + claim.amount().toPlainString()
                + " date=" + claim.date());
        rollup.record(claim.sheetId(), values.by(), before);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: a deferral needs a real date (yyyy-MM-dd) to defer the claim until. */
public class ValidateDefer {
    public void validate(@RequestBody DeferRequest request, Out<ClaimDeferral> deferral)
            throws InvalidClaimStatusException {
        String until = request == null || request.until() == null ? "" : request.until().trim();
        LocalDate date;
        try {
            date = LocalDate.parse(until);
        } catch (DateTimeParseException e) {
            throw new InvalidClaimStatusException("A deferral needs the date it defers the claim until");
        }
        deferral.set(new ClaimDeferral(date, request.by() == null ? "" : request.by().trim()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Stores the deferral, but only while the claim is still OPEN; a change another user made first is refused. */
public class SaveDefer {
    public void save(@Val Claim claim, ClaimRepository claims, Out<Claim> saved) throws InvalidClaimStatusException {
        if (!claims.defer(claim)) {
            throw new InvalidClaimStatusException("The claim was changed by someone else");
        }
        saved.set(claim);
    }
}
package net.officefloor.hq.app.claim;

/** Body of an add or edit of a claim, and who makes it. A blank date takes the sheet's today; corrects is the number of the
 *  claim a correction corrects (blank: none). */
public record ClaimRequest(String amount, String date, String note, String corrects, String by) {
}
package net.officefloor.hq.app.claim;

/** Body of deferring a claim: the date (yyyy-MM-dd) it is deferred until, and who defers it. */
public record DeferRequest(String until, String by) {
}

