package net.officefloor.hq.app.sheet;


/**
 * A sheet: everything else in the app is kept per sheet, keyed by its id. {@code today} is the
 * sheet's own date — every date decision and default date on the sheet uses it, never the clock.
 * An {@code archived} sheet stays visible and refuses every change.
 */
public record Sheet(String id, LocalDate today, boolean archived) {
}
package net.officefloor.hq.app.sheet;


/** Loads a sheet by id. A sheet that was never used starts empty, so every id loads. */
public class LoadSheet {
    public void load(@PathVariable("sheetId") String sheetId, SheetRepository sheets, Out<Sheet> sheet) {
        sheet.set(sheets.find(sheetId.trim()));
    }
}
package net.officefloor.hq.app.sheet;


/** Reads the body and parses the date strictly (2024-02-30 is refused), and who changes it. */
public class ValidateToday {
    public void validate(@RequestBody TodayRequest request, Out<LocalDate> today, Out<TodayBy> by) throws InvalidTodayException {
        by.set(new TodayBy(request == null || request.by() == null ? "" : request.by().trim()));
        String raw = request == null || request.today() == null ? "" : request.today().trim();
        try {
            today.set(LocalDate.parse(raw));
        } catch (DateTimeParseException e) {
            throw new InvalidTodayException("Not a date: " + raw);
        }
    }
}

